  'resumewise-backend': 'ResumeWise (backend)',
  'qr-frontend': 'My QR Code',
  'qr-api': 'My QR Code (API)',
};

const PROJECTS = {
  'aichat-frontend': { name: 'Chat AI - frontend', id: '691331356a3b9a68428ab3.43540470' },
  'aichat-backend': { name: 'Chat AI (emails)', id: '225008626a33e62b328c63.04676982' },
  'realchecker-frontend': { name: 'Realchecker (FE)', id: '964775386a3ce03ecca883.03770715' },
  'realchecker-backend': { name: 'Realchecker (BE)', id: '852017176a3ce11141ecd5.60405885' },
  'mobitrace-frontend': { name: 'Mobitrace', id: '14240418673f52ae29a007.74392007' },
  'myimage-frontend': { name: 'My Image', id: '3070657967b5854be32cb1.65162854' },
  'personality-app': { name: 'Personality.co', id: '31393214664f295f94dd86.76792605' },
  'mywapp-frontend': { name: 'WAPP', id: '4780438967fe077b4e6484.83742970' },
  'mywapp-backend': { name: 'WAPP Backend (emails)', id: '1274536968b58980dc56a0.78363786' },
  'pdfhelp-frontend': { name: 'PDF Editor', id: '1286096867dbf31146afc5.54950617' },
  'pdfhelp-backend': { name: 'PDF Editor (BE- emails)', id: '6744586768821f2c3fe845.13636914' },
  'lovelanguage-frontend': { name: 'Love Language - Static', id: '18228625673dd40ca5a631.46423883' },
  'vinchecker-frontend': { name: 'VIN Checker', id: '2944050668d5010cbd95e8.36175908' },
  'resumewise-backend': { name: 'ResumeWise - backend/emails', id: '9754058268381744ebf048.90929380' },
  'qr-frontend': { name: 'My QR Code', id: '60625870676151e1da46d0.81913446' },
};

const FILE_RE = /(^|\/)en\.json$/;
const EXTRA_BRANCHES = [];

function stop(reason) {
  console.log(reason);
  return [];
}

const ev = $input.first().json;
const body = ev.body || ev;
const headers = ev.headers || {};
const ghEvent = headers['x-github-event'] || headers['X-GitHub-Event'] || 'push';

if (ghEvent === 'ping') return stop('ignored: GitHub ping');
if (ghEvent !== 'push') return stop('ignored: not a push event (' + ghEvent + ')');

const repository = body.repository || {};
const repoFull = repository.full_name;
if (!repoFull) return stop('ignored: payload carries no repository');

const defaultBranch = repository.default_branch || 'main';
const ref = body.ref || '';
if (ref.indexOf('refs/heads/') !== 0) return stop('ignored: ref is not a branch (' + ref + ')');
const branch = ref.substring(11);
const allowedBranches = [defaultBranch].concat(EXTRA_BRANCHES);
if (allowedBranches.indexOf(branch) === -1) return stop('ignored: branch ' + branch + ' is not watched for ' + repoFull);

const commits = body.commits || [];
const paths = [];
for (const c of commits) {
  const files = (c.added || []).concat(c.modified || []);
  for (const f of files) {
    if (FILE_RE.test(f) && paths.indexOf(f) === -1) paths.push(f);
  }
}
if (paths.length === 0) return stop('ignored: no commit in this push touched an en.json in ' + repoFull);

const head = body.head_commit || {};
const beforeSha = body.before || '';
const isFirstPush = /^0+$/.test(beforeSha);
const owner = repoFull.split('/')[0];
const repo = repoFull.split('/')[1];
const label = LABELS[repo] || repo;
const project = PROJECTS[repo] || null;

return paths.map(function (p) {
  return { json: {
    owner: owner,
    repo: repo,
    repoFull: repoFull,
    product: label,
    lokaliseName: project ? project.name : '',
    lokaliseUrl: project ? ('https://app.lokalise.com/project/' + project.id + '/?view=multi') : '',
    path: p,
    branch: branch,
    beforeSha: isFirstPush ? '' : beforeSha,
    afterSha: body.after || '',
    shortSha: (body.after || '').substring(0, 7),
    compareUrl: body.compare || '',
    commitUrl: head.url || '',
    commitMessage: (head.message || '').split(String.fromCharCode(10))[0],
    author: (head.author && head.author.name) || (body.pusher && body.pusher.name) || 'unknown',
  } };
});

const MAX_LISTED = 30;
const TICK = String.fromCharCode(96);
const NL = String.fromCharCode(10);

const metas = $('Normalize Push Event').all();
const news = $('Fetch en.json (new)').all();
const olds = $('Fetch en.json (previous)').all();
const prs = $('Fetch PR For Commit').all();

let pr = null;
for (const it of prs) {
  const j = it.json;
  if (j && !j.error && j.number) { pr = j; break; }
}

function parseJson(text) {
  if (typeof text !== 'string') return null;
  if (text.trim() === '') return null;
  try { return JSON.parse(text); } catch (e) { return null; }
}

function flatten(value, prefix, out) {
  const isPlainObject = value !== null && typeof value === 'object' && !Array.isArray(value);
  if (isPlainObject) {
    const names = Object.keys(value);
    if (names.length === 0 && prefix) out.push(prefix);
    for (const name of names) {
      flatten(value[name], prefix ? prefix + '::' + name : name, out);
    }
  } else if (prefix) {
    out.push(prefix);
  }
  return out;
}

function prLineFor(meta) {
  if (pr) {
    const title = pr.title || '(no title)';
    const who = pr.user && pr.user.login ? ' by ' + pr.user.login : '';
    return NL + 'PR: <' + pr.html_url + '|#' + pr.number + ' ' + title + '>' + who;
  }
  const m = /#(\d+)/.exec(meta.commitMessage || '');
  if (m) {
    const url = 'https://github.com/' + meta.repoFull + '/pull/' + m[1];
    return NL + 'PR: <' + url + '|#' + m[1] + '>';
  }
  return NL + '_No pull request found for this commit - pushed directly._';
}

const results = [];

for (let i = 0; i < metas.length; i++) {
  const meta = metas[i].json;
  const newItem = news[i] ? news[i].json : null;
  const oldItem = olds[i] ? olds[i].json : null;

  const afterJson = parseJson(newItem ? newItem.fileText : null);
  if (afterJson === null) {
    console.log('skipped ' + meta.repoFull + ' ' + meta.path + ': new version could not be read as JSON');
    continue;
  }

  const beforeJson = parseJson(oldItem ? oldItem.fileText : null);
  if (beforeJson === null) {
    console.log('skipped ' + meta.repoFull + ' ' + meta.path + ': previous version unreadable, staying silent instead of reporting every key as new');
    continue;
  }

  const afterKeys = flatten(afterJson, null, []);
  const beforeKeys = flatten(beforeJson, null, []);
  const beforeSet = new Set(beforeKeys);
  const afterSet = new Set(afterKeys);
  const added = afterKeys.filter(function (k) { return !beforeSet.has(k); });
  const removed = beforeKeys.filter(function (k) { return !afterSet.has(k); });

  if (added.length === 0) {
    console.log('no new key in ' + meta.repoFull + ' ' + meta.path + ' (' + removed.length + ' removed, values may have changed)');
    continue;
  }

  const shown = added.slice(0, MAX_LISTED);
  const keyLines = shown.map(function (k) { return TICK + k + TICK; }).join(NL);
  const moreLine = added.length > shown.length ? NL + '_... and ' + (added.length - shown.length) + ' more_' : '';
  const removedLine = removed.length > 0 ? NL + ':warning: ' + removed.length + ' key(s) were also removed in this push.' : '';
  const noun = added.length === 1 ? ' new key in ' : ' new keys in ';
  const header = ':new: *' + meta.product + ' - ' + added.length + noun + meta.path + '*';
  const link = meta.commitUrl ? meta.commitUrl : meta.compareUrl;
  const context = TICK + meta.repoFull + TICK + ' | branch ' + TICK + meta.branch + TICK + ' | <' + link + '|' + meta.shortSha + '>';
  const prLine = prLineFor(meta);
  const lokaliseLine = meta.lokaliseUrl
    ? NL + 'Lokalise: <' + meta.lokaliseUrl + '|' + meta.lokaliseName + '>'
    : '';
  const slackText = header + NL + context + prLine + lokaliseLine + NL + NL + keyLines + moreLine + removedLine;

  results.push({ json: {
    product: meta.product,
    repoFull: meta.repoFull,
    prNumber: pr ? pr.number : null,
    prTitle: pr ? pr.title : null,
    prUrl: pr ? pr.html_url : null,
    lokaliseName: meta.lokaliseName,
    lokaliseUrl: meta.lokaliseUrl,
    branch: meta.branch,
    path: meta.path,
    afterSha: meta.afterSha,
    addedCount: added.length,
    removedCount: removed.length,
    totalKeys: afterKeys.length,
    added: added,
    removed: removed,
    slackText: slackText,
  } });
}

return results;

